class OperationFailure(Exception):
    pass


class RootDirNotFound(Exception):
    pass


class FunctionalityNotImplemented(Exception):
    def __init__(self, category, version):
        self.category = category
        self.version = version

    def __getattr__(self, item):
        err_msg = 'Function "{}" in category: "{}" is not supported in interface version: "{}"'
        raise NotImplementedError(err_msg.format(item, self.category, self.version))


class RequiredParamNotProvided(Exception):
    pass

